def transform(grid):
    h, w = len(grid), len(grid[0])

    def count(panel):
        return sum(v not in (6, 7) for row in panel for v in row)

    def join_horizontal(panels):
        out = [[7] * (6 * len(panels) - 1) for _ in range(5)]
        for i, panel in enumerate(panels):
            for r in range(5):
                out[r][6*i:6*i+5] = panel[r]
                if i < len(panels) - 1:
                    out[r][6*i+5] = 6
        return out

    # Vertical stack of panels: order by decreasing colored-cell count.
    if w == 5 and h > 5:
        panels = [grid[r:r+5] for r in range(0, h, 6)]
        panels.sort(key=count, reverse=True)
        return join_horizontal(panels)

    # A single horizontal row of panels is turned into a vertical stack.
    if h == 5 and w > 5:
        panels = [[grid[r][c:c+5] for r in range(5)] for c in range(0, w, 6)]
        panels.sort(key=count)
        out = []
        for i, panel in enumerate(panels):
            if i:
                out.append([6] * 5)
            out.extend([row[:] for row in panel])
        return out

    # Reorder quadrant panels by increasing colored-cell count.
    row_bars = [r for r in range(h) if all(v == 6 for v in grid[r])]
    col_bars = [c for c in range(w) if all(grid[r][c] == 6 for r in range(h))]
    rs = [0] + [r + 1 for r in row_bars]
    cs = [0] + [c + 1 for c in col_bars]
    panels = []
    for r in rs:
        for c in cs:
            if r + 5 <= h and c + 5 <= w:
                panels.append([grid[r+i][c:c+5] for i in range(5)])
    if not panels:
        return grid
    panels.sort(key=count)
    return join_horizontal(panels)
